`),agent:[`// ========================================`,`// AI AGENT with Tool Use`,`// ========================================`,`const agent = createStore({`,`  status: 'idle',`,`  messages: [],`,`  pendingTool: null,`,`  toolHistory: [],`,`  memory: { known_facts: [] },`,`});`,``,`const tools = {`,`  calculator(expr) {`,`    if (!/^[\\d\\s+\\-*/().,]+$/.test(expr)) return 'Invalid expression';`,`    return Function('"use strict"; return (' + expr + ')')();`,`  },`,`  search(query) {`,`    const db = { 'weather in london': '15C, cloudy', 'capital of france': 'Paris', 'population': '8 billion' };`,`    return db[query.toLowerCase()] || 'No results for: ' + query;`,`  },`,`  note(text) {`,`    const fact = agent.get().memory;`,`    fact.known_facts.push(text);`,`    agent.setKey('memory', { ...fact });`,`    return 'Noted: ' + text;`,`  },`,`};`,``,`agent.on('think', (e) => {`,`  agent.setKey('status', 'thinking');`,`  const tc = e.data && e.data.tool;`,`  if (tc) { agent.emit('execute', tc); return; }`,`  const msg = (e.data && e.data.input) || 'Thinking...';`,`  agent.setKey('messages', (m) => [...m, { role: 'assistant', content: msg }]);`,`  agent.setKey('status', 'done');`,`});`,``,`agent.on('execute', (e) => {`,`  const { name, args } = e.data;`,`  agent.setKey('pendingTool', name);`,`  agent.setKey('status', 'executing');`,`  const tool = tools[name];`,`  if (!tool) { agent.emit('error', { message: 'Unknown tool: ' + name }); return; }`,`  const result = tool(args);`,`  agent.setKey('toolHistory', (h) => [...h, { name, args, result, ts: Date.now() }]);`,`  agent.setKey('pendingTool', null);`,`  console.log('Tool:', name, '=>', result);`,`  agent.emit('think', { input: 'Tool ' + name + ' returned: ' + JSON.stringify(result) });`,`});`,``,`console.log('=== Agent Session ===');`,`agent.emit('think', { input: 'Calculate 45 * 32', tool: { name: 'calculator', args: '45 * 32' } });`,`setTimeout(() => agent.emit('think', { input: 'Search London weather', tool: { name: 'search', args: 'weather in london' } }), 100);`,`setTimeout(() => agent.emit('think', { input: 'Note the result', tool: { name: 'note', args: 'London weather is 15C' } }), 200);`,`setTimeout(() => {`,`  console.log('Memory:', agent.get().memory);`,`  console.log('Tools used:', agent.get().toolHistory.length);`,`}, 400);`].join(`
`),form:[`// ========================================`,`// FORM STATE with Validation`,`// ========================================`,`const form = createStore({`,`  fields: {`,`    name: { value: '', error: null, touched: false },`,`    email: { value: '', error: null, touched: false },`,`    age: { value: '', error: null, touched: false },`,`  },`,`  submitted: false,`,`});`,``,`function validate(field, value) {`,`  if (field === 'name') return !value.trim() ? 'Required' : value.length < 2 ? 'Too short' : null;`,`  if (field === 'email') return !value.includes('@') ? 'Invalid email' : null;`,`  if (field === 'age') { const n = parseInt(value); return isNaN(n) ? 'Must be a number' : n < 18 ? 'Must be 18+' : null; }`,`  return null;`,`}`,``,`form.on('change', (e) => {`,`  const { field, value } = e.data;`,`  const error = validate(field, value);`,`  form.setKey('fields', (f) => ({`,`    ...f,`,`    [field]: { value, error, touched: true },`,`  }));`,`});`,``,`form.on('submit', () => {`,`  const fields = form.get().fields;`,`  let hasError = false;`,`  const next = {};`,`  for (const k in fields) {`,`    const err = validate(k, fields[k].value);`,`    next[k] = { value: fields[k].value, error: err, touched: true };`,`    if (err) hasError = true;`,`  }`,`  form.setKey('fields', next);`,`  form.setKey('submitted', !hasError);`,`  if (!hasError) {`,`    const vals = {}; for (const k in next) vals[k] = next[k].value;`,`    console.log('Submitted:', vals);`,`  } else {`,`    console.log('Form has errors');`,`  }`,`});`,``,`form.emit('change', { field: 'name', value: 'Alice' });`,`form.emit('change', { field: 'email', value: 'alice@' });`,`form.emit('change', { field: 'age', value: '25' });`,`form.emit('submit');`,`form.emit('change', { field: 'email', value: 'alice@example.com' });`,`form.emit('submit');`].join(`
